39	class RadarView extends ChartView {
40	    static type = 'radar';
41	    type = RadarView.type;
42	
43	    private _data: SeriesData<RadarSeriesModel>;
44	
45	    render(seriesModel: RadarSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
46	        const polar = seriesModel.coordinateSystem;
47	        const group = this.group;
48	
49	        const data = seriesModel.getData();
50	        const oldData = this._data;
51	
52	        function createSymbol(data: SeriesData<RadarSeriesModel>, idx: number) {
53	            const symbolType = data.getItemVisual(idx, 'symbol') as string || 'circle';
54	            if (symbolType === 'none') {
55	                return;
56	            }
57	            const symbolSize = symbolUtil.normalizeSymbolSize(
58	                data.getItemVisual(idx, 'symbolSize')
59	            );
60	            const symbolPath = symbolUtil.createSymbol(
61	                symbolType, -1, -1, 2, 2
62	            );
63	            const symbolRotate = data.getItemVisual(idx, 'symbolRotate') || 0;
64	            symbolPath.attr({
65	                style: {
66	                    strokeNoScale: true
67	                },
68	                z2: 100,
69	                scaleX: symbolSize[0] / 2,
70	                scaleY: symbolSize[1] / 2,
71	                rotation: symbolRotate * Math.PI / 180 || 0
72	            });
73	            return symbolPath as RadarSymbol;
74	        }
75	
76	        function updateSymbols(
77	            oldPoints: VectorArray[],
78	            newPoints: VectorArray[],
79	            symbolGroup: graphic.Group,
80	            data: SeriesData<RadarSeriesModel>,
81	            idx: number,
82	            isInit?: boolean
83	        ) {
84	            // Simply rerender all
85	            symbolGroup.removeAll();
86	            for (let i = 0; i < newPoints.length - 1; i++) {
87	                const symbolPath = createSymbol(data, idx);
88	                if (symbolPath) {
89	                    symbolPath.__dimIdx = i;
90	                    if (oldPoints[i]) {
91	                        symbolPath.setPosition(oldPoints[i]);
92	                        graphic[isInit ? 'initProps' : 'updateProps'](
93	                            symbolPath, {
94	                                x: newPoints[i][0],
95	                                y: newPoints[i][1]
96	                            }, seriesModel, idx
97	                        );
98	                    }
99	                    else {
100	                        symbolPath.setPosition(newPoints[i]);
101	                    }
102	                    symbolGroup.add(symbolPath);
103	                }
104	            }
105	        }
106	
107	        function getInitialPoints(points: number[][]) {
108	            return zrUtil.map(points, function (pt) {
109	                return [polar.cx, polar.cy];
110	            });
111	        }
112	        data.diff(oldData)
113	            .add(function (idx) {
114	                const points = data.getItemLayout(idx);
115	                if (!points) {
116	                    return;
117	                }
118	                const polygon = new graphic.Polygon();
119	                const polyline = new graphic.Polyline();
120	                const target = {
121	                    shape: {
122	                        points: points
123	                    }
124	                };
125	
126	                polygon.shape.points = getInitialPoints(points);
127	                polyline.shape.points = getInitialPoints(points);
128	                graphic.initProps(polygon, target, seriesModel, idx);
129	                graphic.initProps(polyline, target, seriesModel, idx);
130	
131	                const itemGroup = new graphic.Group();
132	                const symbolGroup = new graphic.Group();
133	                itemGroup.add(polyline);
134	                itemGroup.add(polygon);
135	                itemGroup.add(symbolGroup);
136	
137	                updateSymbols(
138	                    polyline.shape.points, points, symbolGroup, data, idx, true
139	                );
140	
141	                data.setItemGraphicEl(idx, itemGroup);
142	            })
143	            .update(function (newIdx, oldIdx) {
144	                const itemGroup = oldData.getItemGraphicEl(oldIdx) as graphic.Group;
145	
146	                const polyline = itemGroup.childAt(0) as graphic.Polyline;
147	                const polygon = itemGroup.childAt(1) as graphic.Polygon;
148	                const symbolGroup = itemGroup.childAt(2) as graphic.Group;
149	                const target = {
150	                    shape: {
151	                        points: data.getItemLayout(newIdx)
152	                    }
153	                };
154	
155	                if (!target.shape.points) {
156	                    return;
157	                }
158	                updateSymbols(
159	                    polyline.shape.points,
160	                    target.shape.points,
161	                    symbolGroup,
162	                    data,
163	                    newIdx,
164	                    false
165	                );
166	
167	                saveOldStyle(polygon);
168	                saveOldStyle(polyline);
169	
170	                graphic.updateProps(polyline, target, seriesModel);
171	                graphic.updateProps(polygon, target, seriesModel);
172	
173	                data.setItemGraphicEl(newIdx, itemGroup);
174	            })
175	            .remove(function (idx) {
176	                group.remove(oldData.getItemGraphicEl(idx));
177	            })
178	            .execute();
179	
180	        data.eachItemGraphicEl(function (itemGroup: graphic.Group, idx) {
181	            const itemModel = data.getItemModel<RadarSeriesDataItemOption>(idx);
182	            const polyline = itemGroup.childAt(0) as graphic.Polyline;
183	            const polygon = itemGroup.childAt(1) as graphic.Polygon;
184	            const symbolGroup = itemGroup.childAt(2) as graphic.Group;
185	            // Radar uses the visual encoded from itemStyle.
186	            const itemStyle = data.getItemVisual(idx, 'style');
187	            const color = itemStyle.fill;
188	
189	            group.add(itemGroup);
190	
191	            polyline.useStyle(
192	                zrUtil.defaults(
193	                    itemModel.getModel('lineStyle').getLineStyle(),
194	                    {
195	                        fill: 'none',
196	                        stroke: color
197	                    }
198	                )
199	            );
200	
201	            setStatesStylesFromModel(polyline, itemModel, 'lineStyle');
202	            setStatesStylesFromModel(polygon, itemModel, 'areaStyle');
203	
204	            const areaStyleModel = itemModel.getModel('areaStyle');
205	            const polygonIgnore = areaStyleModel.isEmpty() && areaStyleModel.parentModel.isEmpty();
206	
207	            polygon.ignore = polygonIgnore;
208	
209	            zrUtil.each(['emphasis', 'select', 'blur'] as const, function (stateName) {
210	                const stateModel = itemModel.getModel([stateName, 'areaStyle']);
211	                const stateIgnore = stateModel.isEmpty() && stateModel.parentModel.isEmpty();
212	                // Won't be ignore if normal state is not ignore.
213	                polygon.ensureState(stateName).ignore = stateIgnore && polygonIgnore;
214	            });
215	
216	            polygon.useStyle(
217	                zrUtil.defaults(
218	                    areaStyleModel.getAreaStyle(),
219	                    {
220	                        fill: color,
221	                        opacity: 0.7,
222	                        decal: itemStyle.decal
223	                    }
224	                )
225	            );
226	            const emphasisModel = itemModel.getModel('emphasis');
227	            const itemHoverStyle = emphasisModel.getModel('itemStyle').getItemStyle();
228	            symbolGroup.eachChild(function (symbolPath: RadarSymbol) {
229	                if (symbolPath instanceof ZRImage) {
230	                    const pathStyle = symbolPath.style;
231	                    symbolPath.useStyle(zrUtil.extend({
232	                        // TODO other properties like x, y ?
233	                        image: pathStyle.image,
234	                        x: pathStyle.x, y: pathStyle.y,
235	                        width: pathStyle.width, height: pathStyle.height
236	                    }, itemStyle));
237	                }
238	                else {
239	                    symbolPath.useStyle(itemStyle);
240	                    symbolPath.setColor(color);
241	                    symbolPath.style.strokeNoScale = true;
242	                }
243	
244	                const pathEmphasisState = symbolPath.ensureState('emphasis');
245	                pathEmphasisState.style = zrUtil.clone(itemHoverStyle);
246	                let defaultText = data.getStore().get(data.getDimensionIndex(symbolPath.__dimIdx), idx);
247	                (defaultText == null || isNaN(defaultText as number)) && (defaultText = '');
248	
249	                setLabelStyle(
250	                    symbolPath, getLabelStatesModels(itemModel),
251	                    {
252	                        labelFetcher: data.hostModel,
253	                        labelDataIndex: idx,
254	                        labelDimIndex: symbolPath.__dimIdx,
255	                        defaultText: defaultText as string,
256	                        inheritColor: color as ColorString,
257	                        defaultOpacity: itemStyle.opacity
258	                    }
259	                );
260	            });
261	
262	            toggleHoverEmphasis(
263	                itemGroup, emphasisModel.get('focus'), emphasisModel.get('blurScope'), emphasisModel.get('disabled')
264	            );
265	        });
266	
267	        this._data = data;
268	    }
269	
270	    remove() {
271	        this.group.removeAll();
272	        this._data = null;
273	    }
274	}
